def leg(who, side, pose='plant', step=None):
    a=Ink();near=side=='near_leg'
    if who=='jack' and step is None and pose in ('plant','gather','support'):
        step={'plant':0,'gather':3,'support':6}[pose]
    if step is not None:
        if who=='jack':
            outline=(steps.BOXER_NEAR if near else steps.BOXER_FAR)[step]
            light=(steps.BOXER_LIGHT_NEAR if near else steps.BOXER_LIGHT_FAR)[step]
            foot=(steps.BOXER_BOOT_NEAR if near else steps.BOXER_BOOT_FAR)[step]
        else:
            source=(steps.GINGA_NEAR if near else steps.GINGA_FAR) if who=='amara' else (steps.KARATE_NEAR if near else steps.KARATE)
            outline,light,foot=source[step]
    else:outline,light,foot=(NEAR if near else FAR)[pose]
    if who=='jack' and step is None:
        boots={
          ('far_leg','tuck'):[(74,105),(83,106),(85,111),(89,114),(87,118),(74,118),(71,115),(72,110)],
          ('near_leg','tuck'):[(87,111),(98,111),(96,117),(102,120),(101,124),(88,124),(84,120)],
          ('far_leg','dash'):[(46,129),(54,131),(52,136),(58,139),(56,141),(38,141),(37,138)],
          ('near_leg','dash'):[(109,126),(119,127),(120,134),(130,138),(131,140),(113,140),(109,136)],
          ('far_leg','crouch'):[(64,128),(74,132),(73,136),(76,139),(73,141),(57,141),(55,138)],
          ('near_leg','crouch'):[(114,129),(124,129),(126,135),(134,139),(135,141),(117,141),(113,137)],
        }
        foot=boots.get((side,pose),foot)
    a.shape(outline,(4 if near else 3) if who=='jack' else (14 if near else 13))
    silhouette=np.asarray(a.image).copy()>0
    a.patch(light,(5 if near else 4) if who=='jack' else (16 if near else 15))
    # Secondary fold planes are deliberately shorter than the main highlight.
    if who!='jack':
        a.line(light[:min(3,len(light))],15 if near else 14)
        a.shape(foot,4 if near else 3)
        if len(foot)>3:a.line(foot[:3],5 if near else 4)
    else:
        a.shape(foot,14 if near else 13)
        a.line(foot[:2],15)
        if len(foot)>=5:a.line(foot[3:5],19)
    # The authored silhouette acts as a pencil selection for material marks.
    data=np.asarray(a.image).copy();data[~silhouette]=0;a.image=Image.fromarray(data,'P')
    x,y=zip(*foot);a.box(min(x),min(y),max(x)-min(x)+1,max(y)-min(y)+1)
    return a.part()
